1	#include "rbtree.h"
2	
3	#include <assert.h>
4	#include <stddef.h>
5	#include <stdio.h>
6	#include <stdlib.h>
7	#include <string.h>
8	
9	/* Provided by tests/fault_malloc.c: forces a specific rb_malloc call inside
10	 * rb_create to return NULL, without touching libc malloc. */
11	extern void fault_malloc_arm(int nth_call_to_fail);
12	extern void fault_malloc_disarm(void);
13	extern int fault_malloc_free_count(void);
14	
15	static int value_free_calls = 0;
16	
17	static void counting_free(void *value)
18	{
19	    (void)value;
20	    value_free_calls++;
21	}
22	
23	static void count_cb(const char *key, void *value, void *ctx)
24	{
25	    (void)key;
26	    (void)value;
27	    (*(int *)ctx)++;
28	}
29	
30	/* Tracks which value pointers the tree has actually freed, so insert tests
31	 * can tell "old value freed on overwrite" apart from "value untouched on
32	 * allocation failure" instead of just trusting the return code. */
33	#define MAX_FREED 16
34	static void *freed_values[MAX_FREED];
35	static int freed_count;
36	
37	static void reset_tracking(void)
38	{
39	    freed_count = 0;
40	}
41	
42	static void track_free(void *value)
43	{
44	    assert(freed_count < MAX_FREED);
45	    freed_values[freed_count++] = value;
46	    free(value);
47	}
48	
49	static int was_freed(void *value)
50	{
51	    for (int i = 0; i < freed_count; i++)
52	        if (freed_values[i] == value)
53	            return 1;
54	    return 0;
55	}
56	
57	#define MAX_COLLECT 16
58	typedef struct {
59	    const char *keys[MAX_COLLECT];
60	    int n;
61	} collect_ctx_t;
62	
63	static void collect_cb(const char *key, void *value, void *ctx)
64	{
65	    (void)value;
66	    collect_ctx_t *c = ctx;
67	    assert(c->n < MAX_COLLECT);
68	    c->keys[c->n++] = key;
69	}
70	
71	typedef struct {
72	    const char *name;
73	    rb_value_free_fn value_free;
74	    int fail_at;          /* 0 = no injected malloc failure */
75	    int expect_nonnull;
76	    int expect_free_count; /* rb_free calls during the faulted create; -1 = n/a */
77	} create_case_t;
78	
79	/* Baseline success (with/without value_free), and injected failure on
80	 * each of rb_create's two allocations (the struct, then the nil
81	 * sentinel). Each row that returns non-NULL also exercises
82	 * destroy-after-success being crash-free and memcheck-clean, and now
83	 * checks rb_validate and that value_free is never spuriously invoked
84	 * on an empty tree.
85	 *
86	 * fail_at assumes rb_create makes exactly two rb_malloc calls, in this
87	 * order: the tree struct, then the nil sentinel. If that allocation
88	 * strategy changes, these cases will fail loudly via expect_nonnull
89	 * rather than silently no-op. expect_free_count values: fail_at=1
90	 * fails before anything is allocated, so cleanup frees nothing (0);
91	 * fail_at=2 fails after the tree struct succeeds, so cleanup frees
92	 * exactly that one allocation (1). */
93	static const create_case_t create_cases[] = {
94	    { "create_null_value_free",    NULL,          0, 1, -1 },
95	    { "create_nonnull_value_free", counting_free, 0, 1, -1 },
96	    { "create_fail_first_alloc",   NULL,          1, 0,  0 },
97	    { "create_fail_second_alloc",  NULL,          2, 0,  1 },
98	};
99	
100	static void test_rb_create(void)
101	{
102	    size_t n = sizeof create_cases / sizeof create_cases[0];
103	    /* invariant: each iteration leaves no allocation armed and no tree
104	     * leaked, regardless of whether rb_create succeeded. */
105	    for (size_t i = 0; i < n; i++) {
106	        const create_case_t *c = &create_cases[i];
107	
108	        if (c->fail_at)
109	            fault_malloc_arm(c->fail_at);
110	        rbtree_t *t = rb_create(c->value_free);
111	        if (c->fail_at) {
112	            assert(fault_malloc_free_count() == c->expect_free_count);
113	            fault_malloc_disarm();
114	        }
115	
116	        assert((t != NULL) == c->expect_nonnull);
117	
118	        if (t) {
119	            assert(rb_size(t) == 0);
120	            assert(rb_validate(t) == 0);
121	            assert(rb_find(t, "probe") == NULL);
122	            int calls = 0;
123	            rb_foreach(t, count_cb, &calls);
124	            assert(calls == 0);
125	            value_free_calls = 0;
126	            rb_destroy(t);
127	            assert(value_free_calls == 0);
128	        }
129	        printf("ok - %s\n", c->name);
130	    }
131	
132	    /* Two live trees don't share hidden state. */
133	    {
134	        rbtree_t *a = rb_create(NULL);
135	        rbtree_t *b = rb_create(NULL);
136	        assert(a && b && a != b);
137	        assert(rb_size(a) == 0 && rb_size(b) == 0);
138	        assert(rb_validate(a) == 0 && rb_validate(b) == 0);
139	        rb_destroy(a);
140	        assert(rb_size(b) == 0);
141	        rb_destroy(b);
142	        printf("ok - create_independent_instances\n");
143	    }
144	
145	    /* rb_destroy is documented NULL-safe. */
146	    {
147	        rb_destroy(NULL);
148	        printf("ok - create_destroy_null_safe\n");
149	    }
150	}
151	
152	typedef struct {
153	    const char *name;
154	    const char *key;
155	    void *value;
156	    int fail_at;           /* 0 = no injected malloc failure */
157	    int expect_ok;         /* expect rb_insert to return 0 */
158	} insert_case_t;
159	
160	/* Cases 1-3: baseline success, and injected failure on each of
161	 * rb_insert's internal allocations. Order-agnostic about which
162	 * allocation (node struct vs. key copy) fail_at hits -- the header's
163	 * -1 contract must hold identically either way. */
164	static const insert_case_t insert_cases[] = {
165	    { "insert_into_empty_success", "alpha", "alpha-value", 0, 1 },
166	    { "insert_fails_first_alloc",  "beta",  "beta-value",  1, 0 },
167	    { "insert_fails_second_alloc", "gamma", "gamma-value", 2, 0 },
168	};
169	
170	static void test_rb_insert(void)
171	{
172	    size_t n = sizeof insert_cases / sizeof insert_cases[0];
173	    /* invariant: each iteration gets a fresh tree, so a case's outcome
174	     * never depends on a prior case's inserts. */
175	    for (size_t i = 0; i < n; i++) {
176	        const insert_case_t *c = &insert_cases[i];
177	        rbtree_t *t = rb_create(NULL);
178	        assert(t);
179	
180	        if (c->fail_at)
181	            fault_malloc_arm(c->fail_at);
182	        int rc = rb_insert(t, c->key, c->value);
183	        if (c->fail_at)
184	            fault_malloc_disarm();
185	
186	        assert((rc == 0) == c->expect_ok);
187	        assert(rb_size(t) == (size_t)(c->expect_ok ? 1 : 0));
188	        assert(rb_find(t, c->key) == (c->expect_ok ? c->value : NULL));
189	
190	        rb_destroy(t);
191	        printf("ok - %s\n", c->name);
192	    }
193	
194	    /* Case 4: on allocation failure the tree must not call value_free,
195	     * and the caller must retain sole ownership of value. */
196	    {
197	        rbtree_t *t = rb_create(track_free);
198	        assert(t);
199	        for (int fail_at = 1; fail_at <= 2; fail_at++) {
200	            reset_tracking();
201	            char *v = malloc(8);
202	            assert(v);
203	            strcpy(v, "owned");
204	
205	            fault_malloc_arm(fail_at);
206	            int rc = rb_insert(t, "delta", v);
207	            fault_malloc_disarm();
208	
209	            assert(rc == -1);
210	            assert(!was_freed(v));
211	            assert(rb_size(t) == 0);
212	            free(v);   /* caller still owns it; must not double-free */
213	        }
214	        rb_destroy(t);
215	        printf("ok - insert_failure_value_not_consumed\n");
216	    }
217	
218	    /* Case 5: overwriting an existing key frees the old value via
219	     * value_free, keeps size unchanged, and matches by key content (two
220	     * distinct buffers with identical content, not the same pointer). */
221	    {
222	        rbtree_t *t = rb_create(track_free);
223	        assert(t);
224	        reset_tracking();
225	
226	        char key_first[] = "dup";
227	        char key_second[] = "dup";
228	        char *old_value = malloc(8);
229	        char *new_value = malloc(8);
230	        assert(old_value && new_value);
231	        strcpy(old_value, "old");
232	        strcpy(new_value, "new");
233	
234	        assert(rb_insert(t, key_first, old_value) == 0);
235	        assert(rb_insert(t, key_second, new_value) == 0);
236	
237	        assert(rb_size(t) == 1);
238	        assert(was_freed(old_value));
239	        assert(!was_freed(new_value));
240	        assert(rb_find(t, "dup") == new_value);
241	
242	        rb_destroy(t);
243	        printf("ok - insert_overwrite_frees_old_value\n");
244	    }
245	
246	    /* Case 6: distinct keys each get their own slot; size accumulates
247	     * and lookups don't cross-contaminate. */
248	    {
249	        rbtree_t *t = rb_create(NULL);
250	        assert(t);
251	        assert(rb_insert(t, "a-key", "a-value") == 0);
252	        assert(rb_insert(t, "m-key", "m-value") == 0);
253	        assert(rb_insert(t, "z-key", "z-value") == 0);
254	
255	        assert(rb_size(t) == 3);
256	        assert(strcmp(rb_find(t, "a-key"), "a-value") == 0);
257	        assert(strcmp(rb_find(t, "m-key"), "m-value") == 0);
258	        assert(strcmp(rb_find(t, "z-key"), "z-value") == 0);
259	        assert(rb_find(t, "q-key") == NULL);
260	
261	        rb_destroy(t);
262	        printf("ok - insert_distinct_keys_accumulate_size\n");
263	    }
264	
265	    /* Case 7: an ascending run of inserts forces left-rotations during
266	     * insert-fixup; rebalancing must preserve red-black invariants and
267	     * BST (sorted in-order) structure. */
268	    {
269	        static const char *keys[] = { "a", "b", "c", "d", "e", "f", "g" };
270	        size_t run_len = sizeof keys / sizeof keys[0];
271	        rbtree_t *t = rb_create(NULL);
272	        assert(t);
273	        /* invariant: every insert in this run succeeds before the next
274	         * begins, so size == i+1 after the i-th insert. */
275	        for (size_t i = 0; i < run_len; i++) {
276	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
277	            assert(rb_size(t) == i + 1);
278	        }
279	
280	        assert(rb_validate(t) == 0);
281	
282	        collect_ctx_t collected = {0};
283	        rb_foreach(t, collect_cb, &collected);
284	        assert(collected.n == (int)run_len);
285	        /* invariant: in-order traversal is strictly ascending since all
286	         * inserted keys are distinct. */
287	        for (int i = 0; i + 1 < collected.n; i++)
288	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
289	
290	        rb_destroy(t);
291	        printf("ok - insert_rebalances_ascending_run\n");
292	    }
293	
294	    /* Case 8: a descending run of inserts forces right-rotations during
295	     * insert-fixup; same invariants must hold. */
296	    {
297	        static const char *keys[] = { "g", "f", "e", "d", "c", "b", "a" };
298	        size_t run_len = sizeof keys / sizeof keys[0];
299	        rbtree_t *t = rb_create(NULL);
300	        assert(t);
301	        for (size_t i = 0; i < run_len; i++) {
302	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
303	            assert(rb_size(t) == i + 1);
304	        }
305	
306	        assert(rb_validate(t) == 0);
307	
308	        collect_ctx_t collected = {0};
309	        rb_foreach(t, collect_cb, &collected);
310	        assert(collected.n == (int)run_len);
311	        for (int i = 0; i + 1 < collected.n; i++)
312	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
313	
314	        rb_destroy(t);
315	        printf("ok - insert_rebalances_descending_run\n");
316	    }
317	}
